 "content": "def transform(grid):
    # Fill every hollow rectangular frame's interior with color 7.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = max({v for row in out for v in row}, key=lambda v: sum(row.count(v) for row in out))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r,c) in seen:
                continue
            todo=[(r,c)]; seen.add((r,c)); cells=[]
            while todo:
                y,x=todo.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and out[yy][xx]==color:
                        seen.add((yy,xx)); todo.append((yy,xx))
            y0=min(y for y,x in cells); y1=max(y for y,x in cells)
            x0=min(x for y,x in cells); x1=max(x for y,x in cells)
            border={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if y in (y0,y1) or x in (x0,x1)}
            inside=[(y,x) for y in range(y0+1,y1) for x in range(x0+1,x1)]
            if set(cells)==border and inside and all(out[y][x]==bg for y,x in inside):
                for y,x in inside: out[y][x]=7
    return out

if __name__ == '__main__':
    import json
    g=json.loads(input())
    print(json.dumps(transform(g)))
